insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:haricot vert', 'green bean', array['en:green bean']::text[], 'list', $r$[{"title":"Thai green chicken curry","intro":"Chicken and vegetables in coconut milk, flavoured with green curry paste and basil.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"thai green curry chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":1,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the curry paste in the oil for 1 minute.","timer":null},{"text":"Add the chicken strips and brown them for 4 minutes.","timer":{"label":"Cooking","min":4}},{"text":"Pour in the coconut milk, add the vegetables and cook for 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the soy sauce, the juice of the lime and the basil. Serve with rice.","timer":null}]},{"title":"Soupe au pistou","intro":"The Provençal soup of summer vegetables and beans, with its basil pistou.","minutes":60,"calories":380,"difficulty":"Facile","imageSearch":"soupe au pistou","veg":true,"oven":false,"cold":false,"missing":"","origin":"Provençal speciality","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":200,"unit"