n the butter with the chopped garlic.","timer":{"label":"Pan","min":3}},{"text":"Sprinkle with parsley.","timer":null}],"kids":true},{"title":"Minestrone with pesto","intro":"Minestrone, lifted with a spoonful of pesto when you serve it.","minutes":45,"calories":330,"difficulty":"Facile","imageSearch":"minestrone pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"macaroni","plural":"macaroni","qty":80,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and carrots in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the potato, courgette, chopped green beans, 1 l of water and the stock cube. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the pasta and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Serve with a spoonful of pesto in each bowl.","timer":null}]},{"title":"Green vegetable curry","intro":"A fragrant Thai curry, with basil and lime.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"thai green vegetable curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl