beans.","timer":null},{"text":"Sauté for 3 min.","timer":null}],"kids":true},{"title":"Vegetable paella","intro":"A colourful paella with sunny vegetables.","minutes":45,"calories":480,"difficulty":"Moyen","imageSearch":"vegetable paella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"round-grain rice","plural":"round-grain rice","qty":350,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"pea","plural":"peas","qty":100,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and peppers in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the courgette, beans and diced tomatoes for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the rice, the saffron and 1 l of hot stock.","timer":null},{"text":"Cook for 20 minutes without stirring, adding the peas at the end.","timer":{"label":"Cooking","min":20}}]}]$r$::jsonb, 'claude')
