h the forks.","timer":null}]},{"title":"Spaghetti carbonara","intro":"The real carbonara: eggs, pecorino and guanciale, with no cream.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"egg yolk","plural":"egg yolks","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated pecorino","plural":"grated pecorino","qty":60,"unit":"g","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti in boiling salted water.","timer":{"label":"Pasta","min":10}},{"text":"Brown the guanciale slices in a pan for 5 min, with no added fat.","timer":{"label":"Pan","min":5}},{"text":"Beat the yolks, the whole egg, the pecorino and plenty of pepper.","timer":null},{"text":"Drain the pasta, keeping a little cooking water, and put it in the pan off the heat.","timer":null},{"text":"Pour in the eggs, stirring quickly, with a little cooking water to make a creamy sauce.","timer":null}]},{"title":"Homemade burger","intro":"A juicy patty, melted cheddar, salad and a homemade sauce in a brioche bun.","minutes":25,"calories":720,"difficulty":"Facile","imageSearch":"homemade cheeseburger","veg":false,"oven":false,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"burger bun","plural":"burger buns","qty":4,"unit":"","have":false},{"name":"beef burger patty","plural":"beef burger patties","qty":4,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"slices","have":false},{"name":"tomato","plural":"tomatoes","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"gherkin","plural":"gherkins","qty":4,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":2,"unit":"tbsp","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the ketchup and mayonnaise to make the sauce.","timer":null},{"text":"Toast the halved buns for 1 minute in a pan.","timer":{"label":"Pan","min":1}},{"text":"Cook the patties for 3 minutes on each side, season with salt and pepper, and put the cheddar on top at the end.","timer":{"label":"Pan","min":6}},{"text":"Build the burgers: sauce, lettuce, patty, tomato, onion and gherkins.","timer":null}],"kids":true,"makes":{"n":4,"one":"burger","many":"burgers"}}]$r$::jsonb, 'claude')
