insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poisson', 'fish', array['en:fish']::text[], 'list', $r$[{"title":"Salmon poke bowl","intro":"Vinegared rice, raw salmon marinated in soy, avocado, cucumber and sesame.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"salmon poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"Hawaiian dish","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":250,"unit":"g","have":false},{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":2,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"edamame bean","plural":"edamame beans","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":2,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Cook the rice, mix it with the rice vinegar and leave it to cool a little.","timer":{"label":"Cooking","min":15}},{"text":"Cut the salmon into cubes and marinate it in the soy sauce for 10 minutes.","timer":{"label":"Marinate","min":10}},{"text":"Slice the avocado and cucumber.","timer":null},{"text":"In bowls, arrange the rice, salmon, vegetables, edamame, sesame seeds and spring onion.","timer":null}]},{"title":"Salt cod brandade","intro":"Salt cod mixed into a garlic and olive oil mash, then browned in the oven.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"brandade cod potato gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality from Nîmes","serves":4,"items":[{"name":"salt cod","plural":"salt cod","qty":500,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":700,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"The day before, soak the cod in cold water, changing the water 3 times.","timer":null},{"text":"Poach the cod for 10 min in the milk, then flake it.","timer":{"label":"Cooking","min":10}},{"text":"Boil the potatoes for 20 min and mash them.","timer":{"label":"Cooking","min":20}},{"text":"Mix the mash, cod, chopped garlic, oil and a little of the cooking milk. Add pepper.","timer":null},{"text":"Pour into a dish, sprinkle with breadcrumbs and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}]},{"title":"Thai chicken and coconut soup","intro":"Tom kha kai: chicken in a coconut broth with lemongrass and lime.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"tom kha gai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai recipe","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring 50 cl of water to a simmer with the stock cube, bruised lemongrass and sliced ginger.","timer":{"label":"Cooking","min":10}},{"text":"Add the coconut milk and the chicken in thin strips, and cook for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Add the sliced mushrooms and cook for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Off the heat, add the lime juice and fish sauce.","timer":null},{"text":"Sprinkle with coriander.","timer":null}]},{"title":"Salmon maki","intro":"Rolls of vinegared rice and nori seaweed, with salmon and cucumber.","minutes":70,"calories":350,"difficulty":"Difficile","imageSearch":"salmon maki sushi","veg":false,"oven":false,"cold":true,"missing":"","origin":"Japanese recipe","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":300,"unit":"g","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":5,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"nori sheet","plural":"nori sheets","qty":5,"unit":"","have":false},{"name":"fresh salmon","plural":"fresh salmon","qty":250,"unit":"g","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Rinse the rice until the water runs clear, then cook it for 12 minutes with 36 cl of water, covered.","timer":{"label":"Cooking","min":12}},{"text":"Leave to rest for 10 minutes, then mix with the vinegar, the sugar and a pinch of salt. Leave to cool.","timer":null},{"text":"Cut the salmon and the cucumber into sticks.","timer":null},{"text":"Spread a thin layer of rice on a nori sheet and lay the salmon and cucumber along one edge.","timer":null},{"text":"Roll up tightly with a bamboo mat, then cut into 6 with a wet knife.","timer":null},{"text":"Serve with the soy sauce.","timer":null}],"makes":{"n":40,"one":"maki roll","many":"maki rolls"}},{"title":"Homemade blinis","intro":"Small, thick, fluffy pancakes to top with cream and smoked salmon.","minutes":40,"calories":180,"difficulty":"Facile","imageSearch":"blinis smoked salmon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"melted butter","plural":"melted butter","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, baking powder, egg yolks, milk and melted butter.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Cook small rounds of batter for 1 min on each side in a buttered pan.","timer":{"label":"Pan","min":2}},{"text":"Top each blini with crème fraîche, salmon and dill.","timer":null}],"makes":{"n":24,"one":"blini","many":"blinis"}},{"title":"Salmon tartare","intro":"Raw salmon cut by hand, with lime, shallot and herbs.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"salmon tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":3,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the salmon into small, even cubes.","timer":null},{"text":"Mix with the chopped shallot, chives, oil, the juice of the limes, salt and pepper.","timer":null},{"text":"Chill for 10 min before serving.","timer":{"label":"Chill","min":10}}]},{"title":"Sesame-seared tuna steak","intro":"Tuna seared in sesame seeds, pink in the middle, with a soy sauce.","minutes":15,"calories":320,"difficulty":"Moyen","imageSearch":"seared tuna steak sesame","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tuna steak","plural":"tuna steaks","qty":4,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":4,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"oil","plural":"oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Coat the steaks in sesame seeds.","timer":null},{"text":"Sear them for 1 min on each side over a very high heat.","timer":{"label":"Pan","min":2}},{"text":"Cut them into slices.","timer":null},{"text":"Serve with the soy sauce mixed with the lime juice.","timer":null}]},{"title":"Niçoise salad","intro":"The salad from the South: tuna, hard-boiled eggs, tomatoes, olives and anchovies, with an olive oil dressing.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"nicoise salad tuna egg","veg":false,"oven":false,"cold":true,"missing":"","origin":"Speciality from Nice","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":200,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"anchovy","plural":"anchovies","qty":8,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 10 minutes, then cool them.","timer":{"label":"Eggs","min":10}},{"text":"Cut the tomatoes into wedges, the pepper into strips and the onion into thin rings.","timer":null},{"text":"Arrange the vegetables, tuna, quartered eggs, olives and anchovies.","timer":null},{"text":"Drizzle with a dressing of oil, vinegar, salt and pepper.","timer":null}]},{"title":"Monkfish armoricaine","intro":"Monkfish in a tomato sauce with white wine and cognac, Breton style.","minutes":45,"calories":380,"difficulty":"Moyen","imageSearch":"monkfish armoricaine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"monkfish","plural":"monkfish","qty":800,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":3,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"cognac","plural":"cognac","qty":3,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the monkfish into medallions and brown them for 3 min. Flambé with the cognac.","timer":{"label":"Pan","min":3}},{"text":"Take out the monkfish and fry the shallots and the garlic.","timer":null},{"text":"Add the wine and the tomatoes, and let it reduce for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add the cream, put the monkfish back and cook for 8 min.","timer":{"label":"Cooking","min":8}}]},{"title":"Baked sea bream","intro":"A whole sea bream roasted in the oven with lemon, fennel and herbs.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"baked sea bream","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gutted sea bream","plural":"gutted sea breams","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"fennel","plural":"fennel","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the sliced fennel in the bottom of a dish with 2 tbsp of oil.","timer":null},{"text":"Slip lemon slices, garlic and thyme inside the fish, and season with salt and pepper.","timer":null},{"text":"Lay them on the fennel, drizzle with the rest of the oil and bake for 25 min.","timer":{"label":"Oven","min":25}}]},{"title":"Pork nems","intro":"Crispy fried rolls filled with pork, vermicelli and wood ear mushrooms.","minutes":60,"calories":350,"difficulty":"Difficile","imageSearch":"vietnamese spring rolls nem","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":16,"unit":"","have":false},{"name":"minced pork","plural":"minced pork","qty":300,"unit":"g","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":50,"unit":"g","have":false},{"name":"dried wood ear mushroom","plural":"dried wood ear mushrooms","qty":1