"unit":"","have":false}],"steps":[{"text":"Dry-fry the halved onion and ginger in a pan until charred.","timer":{"label":"Pan","min":5}},{"text":"Put them in 1.5 litres of water with the stock cubes, the star anise and the fish sauce, and simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Cook the noodles according to the packet.","timer":null},{"text":"Slice the raw beef very thinly.","timer":null},{"text":"Put the noodles and the beef in bowls and pour the boiling broth over them: it cooks the meat.","timer":null},{"text":"Serve with the bean sprouts, the coriander and the lime.","timer":null}]},{"title":"Baked salmon fillets","intro":"Tender salmon fillets baked in the oven with lemon, dill and a drizzle of olive oil.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"baked salmon fillet lemon dill","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Place the fillets in a dish, skin-side down.","timer":null},{"text":"Drizzle with oil, add lemon slices, the dill, salt and pepper.","timer":null},{"text":"Bake for 15 min: the middle should still be slightly translucent.","timer":{"label":"Oven","min":15}}]},{"title":"Trout with almonds","intro":"Trout fried golden in butter with toasted flaked almonds.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"trout almonds","veg":false,"oven":false,"cold":false,"missing":"","origin":"French classic","serves":4,"items":[{"name":"trout","plural":"trout","qty