ella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says.","timer":{"label":"Cooking","min":8}},{"text":"Melt the gorgonzola and the parmesan in the cream.","timer":null},{"text":"Mix with the pasta in a dish and cover with mozzarella and Emmental.","timer":null},{"text":"Bake for 15 minutes.","timer":{"label":"Oven","min":15}}],"kids":true},{"title":"Pesto pasta salad","intro":"A vegetarian pasta salad, green with pesto.","minutes":20,"calories":470,"difficulty":"Facile","imageSearch":"pesto pasta salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":300,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"rocket","plural":"rocket","qty":50,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta and rinse it under cold water.","timer":{"label":"Cooking","min":10}},{"text":"Halve the cherry tomatoes.","timer":null},{"text":"Toss the pasta with the pesto and tomatoes.","timer":null},{"text":"Add the rocket and a few Parmesan shavings.","timer":null}],"kids":true}]$r$::jsonb, 'claude')
