insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:quinoa', 'quinoa', array[]::text[], 'list', $r$[{"title":"Buddha bowl","intro":"A colourful, filling bowl: quinoa, roasted chickpeas, vegetables, avocado and tahini sauce.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"red cabbage","plural":"red cabbages","qty":0.25,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"tahini","plural":"tahini","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Put the diced sweet potato and the chickpeas on a baking tray with the oil, paprika and salt. Bake for 25 min.","timer":{"label":"Oven","min":25}},{"text":"Cook the quinoa for 12 min.","timer":{"label":"Cooking","min":12}},{"text":"Mix the tahini, the lemon juice and a little water to make the sauce.","timer":null},{"text":"Build the bowls with the quinoa, grated vegetables, avocado, chickpeas and sweet potato, then add the sauce.","timer":null}]},{"title":"Quinoa salad","intro":"Quinoa with cucumber, tomatoes, feta and herbs, a bit like a tabbouleh.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Rinse the quinoa, then cook it in salted water for 12 minutes. Drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Dice the cucumber and halve the tomatoes.","timer":null},{"text":"Toss with the quinoa, the crumbled feta and the chopped mint.","timer":null},{"text":"Dress with lemon juice and olive oil.","timer":null}]},{"title":"Avocado quinoa salad","intro":"A Mexican-style quinoa salad, filling and vegan.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"quinoa avocado black bean salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Mexican-inspired","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"kidney bean","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes, drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Rinse the kidney beans and sweetcorn.","timer":null},{"text":"Dice the avocados and sprinkle with lime juice.","timer":null},{"text":"Toss everything together with the coriander, oil and the rest of the juice.","timer":null}]},{"title":"Chicken quinoa salad","intro":"The quinoa salad as a full meal, with chicken.","minutes":30,"calories":470,"difficulty":"Facile","imageSearch":"quinoa chicken salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes, drain and leave to cool.","timer":{"label":"Cooking","min":12}},{"text":"Grill the chicken for 6 minutes on each side and cut into strips.","timer":{"label":"Pan","min":12}},{"text":"Chop the cucumber and tomatoes.","timer":null},{"text":"Toss everything with the lemon juice and oil.","timer":null}]},{"title":"Quinoa tabbouleh","intro":"A fresh tabbouleh made with quinoa.","minutes":25,"calories":330,"difficulty":"Facile","imageSearch":"quinoa tabbouleh","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes in salted water and leave it to cool.","timer":{"label":"Cooking","min":12}},{"text":"Cut the vegetables into small cubes.","timer":null},{"text":"Mix with the quinoa, the mint, the juice of the lemons, the oil, salt and pepper.","timer":null}]}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:semoule', 'couscous', array[]::text[], 'list', $r$[{"title":"Couscous with chicken and merguez","intro":"Couscous grains, a spiced broth, tender vegetables, chicken and merguez sausages.","minutes":90,"calories":720,"difficulty":"Moyen","imageSearch":"couscous chicken merguez vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":400,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"merguez","plural":"merguez","qty":4,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken and onions in the oil in a large pot.","timer":null},{"text":"Add the spices, tomatoes, and the carrots and turnips in chunks, then 1.5 l of water. Simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Add the courgettes and chickpeas and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Grill the merguez for 10 minutes.","timer":{"label":"Grill","min":10}},{"text":"Pour over the same volume of boiling salted water as couscous, cover for 5 minutes, then fluff with the butter. Serve with the broth, vegetables and meats.","timer":{"label":"Rest","min":5}}],"kids":true},{"title":"Couscous tabbouleh","intro":"Fresh couscous with tomato, cucumber, mint and lemon.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"couscous tabbouleh salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":250,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Pour 25 cl of boiling salted water over the couscous, cover for 5 minutes and fluff with a fork.","timer":{"label":"Rest","min":5}},{"text":"Cut the tomatoes, cucumber and onion into small cubes.","timer":null},{"text":"Mix with the couscous, the chopped mint and parsley, the juice of the lemons, the oil, salt and pepper.","timer":null},{"text":"Chill for 1 hour.","timer":{"label":"Chill","min":60}}],"kids":true},{"title":"Quick chicken couscous","intro":"The taste of couscous for a weeknight.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"quick chicken couscous","veg":false,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chopped chicken and the onion in the oil with the spices for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the diced carrots and courgettes, the tomatoes and 50 cl of water. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the chickpeas for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Prepare the couscous and serve with the broth.","timer":null}],"kids":true},{"title":"Vegetable couscous","intro":"A generous, fragrant vegetable couscous.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"vegetable couscous","veg":true,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":350,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"pumpkin","plural":"pumpkin","qty":300,"unit":"g","have":false},{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"raisin","plural":"raisins","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions in the oil with the spices.","timer":null},{"text":"Add the tomatoes, carrots, turnips and 1.2 l of water. Simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the courgettes, pumpkin, chickpeas and raisins, and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Prepare the couscous with the same volume of boiling salted water and fluff it.","timer":null}]}]$r$::jsonb, 'claude')
