insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:chocolat', 'chocolate', array['en:chocolate']::text[], 'list', $r$[{"title":"Pears belle Hélène","intro":"Pears poached in vanilla syrup, covered with hot chocolate.","minutes":40,"calories":330,"difficulty":"Facile","imageSearch":"poire belle helene","veg":true,"oven":false,"cold":true,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"liquid cream","plural":"liquid cream","qty":15,"unit":"cl","have":false},{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false}],"steps":[{"text":"Bring 1 litre of water to the boil with the sugar and the split vanilla pod.","timer":null},{"text":"Peel the pears, leaving the stalk on, and poach them in the syrup for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Leave them to cool in the syrup.","timer":null},{"text":"Melt the chocolate in the hot cream.","timer":null},{"text":"Serve each pear with a scoop of ice cream and the chocolate sauce.","timer":null}],"dessert":true},{"title":"Chocolate éclairs","intro":"Long choux buns filled with chocolate custard and iced with chocolate.","minutes":90,"calories":380,"difficulty":"Difficile","imageSearch":"chocolate eclairs","veg":true,"oven":true,"cold":false,"missing":"","origin":"French pastry","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":40,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Bring 15 cl of water, the butter and a pinch of salt to the boil, tip in the flour and stir until the dough comes away from the pan.","timer":null},{"text":"Off the heat, add 4 eggs one by one. Pipe 12 cm lengths onto a tray.","timer":null},{"text":"Bake for 30 min without opening the oven.","timer":{"label":"Oven","min":30}},{"text":"Make a custard with the milk, 3 eggs, the sugar and the cornflour, and stir in 100 g of chocolate.","timer":{"label":"Cooking","min":5}},{"text":"Fill the cold éclairs and cover them with the rest of the melted chocolate.","timer":null}],"dessert":true,"makes":{"n":12,"one":"éclair","many":"éclairs"}},{"title":"Chocolate cake","intro":"The cake that is gooey in the middle, everyone's favourite dessert.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"chocolate cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate and butter together.","timer":null},{"text":"Whisk the eggs with the sugar, then add the chocolate and flour.","timer":null},{"text":"Pour into a buttered tin and bake for 22 min: the centre should still wobble.","timer":{"label":"Oven","min":22}}],"kids":true,"dessert":true},{"title":"Chocolate tart","intro":"A sweet shortcrust base with a rich dark chocolate ganache.","minutes":50,"calories":450,"difficulty":"Moyen","imageSearch":"chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Blind bake the pastry for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Heat the cream and pour it over the chopped chocolate.","timer":null},{"text":"Stir, then add the butter and the beaten egg.","timer":null},{"text":"Pour into the pastry case and bake for 10 min at 150 °C.","timer":{"label":"Oven","min":10}},{"text":"Leave to cool for at least 1 h.","timer":null}],"dessert":true},{"title":"Chocolate chip cookies","intro":"Cookies that are crisp at the edges and soft in the middle.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"chocolate chip cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":0.5,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the soft butter and sugar, then add the egg.","timer":null},{"text":"Add the flour, baking powder, a pinch of salt and the chocolate chips.","timer":null},{"text":"Shape into balls and place them well apart on a baking tray.","timer":null},{"text":"Bake for 10 min: they should stay soft in the middle.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":16,"one":"cookie","many":"cookies"}},{"title":"Chocolate cream dessert","intro":"A smooth, creamy chocolate dessert, like the ones in shop-bought pots.","minutes":15,"calories":250,"difficulty":"Facile","imageSearch":"chocolate pudding cups","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":30,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the cornflour and the cocoa with a little cold milk.","timer":null},{"text":"Heat the rest of the milk with the sugar and the chopped chocolate.","timer":null},{"text":"Add the cornflour mixture and stir until the cream thickens.","timer":{"label":"Cooking","min":3}},{"text":"Pour into pots and chill for 2 h.","timer":null}],"kids":true,"dessert":true},{"title":"Chocolate yule log","intro":"A rolled sponge filled and covered with chocolate ganache, for Christmas dinner.","minutes":70,"calories":420,"difficulty":"Difficile","imageSearch":"chocolate yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"Christmas tradition","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":250,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":40,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qt